

var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"WildRespinAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){

		var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.brd.bqm!=undefined){
			
			if(gameController.qpd!=parseInt(tmpMess[1])){
				
			gameController.qpd=parseInt(tmpMess[1]);	
			gameController.yrc=parseInt(tmpMess[1]);	
			gameController.brd.bqm.ymn("creditd", "#bwb", [gameController.eod(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
